CALCULATE (
    DISTINCTCOUNT ( 'Fact Tangata Whaiora Referral'[Tangata Whaiora ID] ),
    'Fact Tangata Whaiora Referral'[Referral Status] IN { "Accepted", "Accepted and Discharged" },
